.slider-wrapper {
  width: 100%;
  position: relative;
}
.slider-wrapper i.slider-controls {
  position: absolute;
  top: 50vh;
  transform: translateY(-50%);
  font-size: 52px;
  height: 56px;
  width: 56px;
  background: var(--main-color);
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.23);
  border-radius: 50%;
  cursor: pointer;
  line-height: 32px;
  text-align: center;
  transition: 0.3s ease;
  z-index: 3;
  padding: 2px;
  color: var(--white);
}
.slider-wrapper i.slider-controls:first-child {
  left: var(--margin);
}
.slider-wrapper i.slider-controls:last-child {
  right: var(--margin);
}
.slider-wrapper i.slider-controls:active {
  transform: translateY(-50%) scale(0.85);
}
.slider-wrapper .slider {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 100%;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  margin: 0;
  padding: 0;
}
.slider-wrapper .slider.no-transition {
  scroll-behavior: auto;
}
.slider-wrapper .slider.dragging {
  scroll-behavior: auto;
  scroll-snap-type: none;
}
.slider-wrapper .slider.dragging .card {
  user-select: none;
  cursor: grab;
}
.slider-wrapper .slider .slide {
  scroll-snap-align: start;
  width: 100%;
  display: flex;
  height: 100%;
  overflow: hidden;
  position: relative;
  margin: 0;
  padding: 0;
}
.slider-wrapper .slider .slide > .img, .slider-wrapper .slider .slide > .wp-block-image {
  position: absolute;
  display: block;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
.slider-wrapper .slider .slide > .img img, .slider-wrapper .slider .slide > .wp-block-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.slider-wrapper .slider .slide > .caption {
  position: absolute;
  display: block;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
.slider-wrapper .slider .slide.active > .caption {
  position: relative;
}

body.consent-pending {
  overflow: hidden;
}

#consent-overlay {
  position: fixed;
  inset: 0;
  z-index: 900;
  background-color: rgba(0, 0, 0, 0.75);
  transition: opacity 0.3s ease;
}
#consent-overlay.gone {
  opacity: 0;
  pointer-events: none;
}

#consent-banner {
  position: fixed;
  z-index: 901;
  bottom: 0;
  right: 10%;
  width: 75%;
  display: none;
  flex-flow: row wrap;
  align-items: flex-start;
  gap: calc(var(--padding) * 0.5);
  padding: calc(var(--padding) * 2);
  background: var(--gingerbread);
  border-top-left-radius: 15px;
  border-top-right-radius: 15px;
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.25);
  transition: transform 0.3s ease, box-shadow 0.3s ease, padding 0.3s ease;
  transform: translate(0, calc(var(--padding) * 0.25));
}
@media (min-width: 768px) {
  #consent-banner {
    width: 50%;
  }
}
#consent-banner:hover {
  transform: translate(0, 0);
  box-shadow: 0 0 10px 3px rgba(0, 0, 0, 0.25);
}
#consent-banner.open {
  display: flex;
}
#consent-banner.mini {
  display: flex;
  gap: 0;
  padding: calc(var(--padding) * 0.5);
  width: auto;
  cursor: pointer;
  transform: none;
}
#consent-banner.mini [data-consent-close],
#consent-banner.mini .consent-label,
#consent-banner.mini .consent-buttons {
  display: none;
}
#consent-banner.mini p.cookie-icon {
  width: auto;
  padding: calc(var(--padding) * 0.5);
}
#consent-banner.mini .cookie-banner-content {
  width: auto;
}
#consent-banner.mini p.consent-status {
  display: inline-block;
  color: var(--white);
  font-weight: 700;
  font-style: italic;
}
#consent-banner [data-consent-close] {
  position: absolute;
  top: calc(var(--padding) * 1.5);
  right: calc(var(--padding) * 1.5);
  display: inline-block;
  line-height: 1;
  font-size: var(--h4);
  color: var(--white) !important;
  padding: 0;
  cursor: pointer;
}
#consent-banner [data-consent-close]:hover {
  color: var(--black) !important;
}
#consent-banner p.cookie-icon {
  width: 50px;
  margin: 0;
  font-size: var(--h1);
  line-height: calc(var(--h1) * 1.25);
}
@media (min-width: 768px) {
  #consent-banner p.cookie-icon {
    width: 60px;
  }
}
@media (min-width: 992px) {
  #consent-banner p.cookie-icon {
    width: 80px;
  }
}
#consent-banner .cookie-banner-content {
  width: calc(100% - 50px);
}
@media (min-width: 768px) {
  #consent-banner .cookie-banner-content {
    width: calc(100% - 60px);
  }
}
@media (min-width: 992px) {
  #consent-banner .cookie-banner-content {
    width: calc(100% - 80px);
  }
}
#consent-banner .cookie-banner-content .consent-label {
  margin-bottom: var(--margin);
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc {
  margin-top: 0;
  padding-right: 40px;
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc a {
  color: var(--white) !important;
  text-decoration: underline;
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc a:hover {
  color: var(--black) !important;
}
#consent-banner .cookie-banner-content p.consent-status {
  display: none;
  font-size: calc(var(--p) * 0.8);
  line-height: calc(var(--h3) * 1.5);
  margin: 0 calc(var(--margin) * 0.5);
}

#debug-box {
  position: fixed;
  z-index: 999;
  bottom: 0;
  right: 0;
  left: 0;
  text-align: right;
  border-left: 2px solid var(--black);
  display: flex;
  flex-flow: column wrap;
  align-items: start;
  padding: 0;
  max-width: 50%;
}
@media (min-width: 768px) {
  #debug-box {
    bottom: 0;
    border-bottom: 2px solid var(--black);
    border-left: none;
    flex-flow: row wrap;
    padding: 0 calc(var(--padding) * 0.5);
    max-width: none;
  }
}
#debug-box .debug-data {
  margin-bottom: calc(var(--margin) * 0.25);
  margin-right: 0;
}
@media (min-width: 768px) {
  #debug-box .debug-data {
    margin-bottom: 0;
    margin-right: calc(var(--margin) * 0.5);
  }
}
#debug-box .debug-data p {
  display: block;
  background: var(--black);
  padding: calc(var(--padding) * 0.5) calc(var(--padding) * 0.75);
  text-align: center;
  width: auto;
  line-height: 1;
}
@media (min-width: 768px) {
  #debug-box .debug-data p {
    margin: calc(var(--margin) * 0.25) calc(var(--margin) * 0.25) 0 calc(var(--margin) * 0.25);
  }
}

.dev-tag {
  position: fixed;
  bottom: 0;
  right: 0;
  transform: rotate(-45deg) translate(15px, 30px);
  transform-origin: center;
  width: 80px;
  height: 40px;
  z-index: 999;
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease;
}
.dev-tag p {
  padding: calc(var(--margin) * 0.5);
  color: #fff;
  margin: 0;
  text-align: center;
  font-size: calc(var(--p) * 0.75);
  line-height: 1;
  font-weight: 700;
}
@media (min-width: 768px) {
  .dev-tag p {
    padding: calc(var(--margin) * 0.75);
  }
}
.dev-tag:hover {
  box-shadow: 0 0 0 5px rgba(0, 0, 0, 0.05);
}
.dev-tag.dev {
  background: var(--warning);
}
.dev-tag.prod {
  background: var(--success);
}

#msg {
  position: fixed;
  z-index: 999;
  top: 75%;
  right: 0;
  transform: translate(0, -50%);
  text-align: right;
  display: flex;
  flex-flow: column wrap;
